style.css:
@-moz-document domain("mail.google.com") {
/* ==================================================
   PINKIE — MY MELODY INSPIRED GMAIL THEME
   ================================================== */

:root {
    --pink-main: #f6a9bd;
    --pink-soft: #ffdce6;
    --pink-pale: #fff1f5;
    --cream: #fffaf3;
    --brown: #6f4c4c;
    --brown-soft: #9a7474;
    --white: #fffdfd;
}

/* ---------- WHOLE PAGE ---------- */
html,
body,
.nH,
.aeJ,
.aeN {
    background: var(--pink-pale) !important;
}

body {
    color: var(--brown) !important;
}

/* ---------- TOP HEADER ---------- */
header,
.gb_Ld,
.gb_Fd,
.gb_Kd {
    background: linear-gradient(
        90deg,
        #ffd8e3,
        #fff4f1,
        #ffd8e3
    ) !important;

    border-bottom: 2px solid #efb2c1 !important;
}

/* ---------- SEARCH BAR ---------- */
form[role="search"] {
    background: var(--cream) !important;
    border: 2px solid var(--pink-main) !important;
    border-radius: 22px !important;
    box-shadow: 0 3px 8px rgba(177, 111, 127, 0.12) !important;
}

form[role="search"] input {
    color: var(--brown) !important;
}

/* ---------- SIDEBAR ---------- */
.aeN {
    background: #ffe8ee !important;
    border-right: 2px solid #f2c3ce !important;
}

/* Selected sidebar item */
.aHS-bnt .qj,
.aHS-bnt,
.aHS-bnt:hover {
    border-radius: 0 22px 22px 0 !important;
}

/* ---------- COMPOSE BUTTON ---------- */
.T-I.T-I-KE {
    background: linear-gradient(
        180deg,
        #f8b2c4,
        #ef98b0
    ) !important;

    color: #704550 !important;
    border: 2px solid #e88ea6 !important;
    border-radius: 22px !important;
    box-shadow: 0 4px 8px rgba(141, 82, 100, 0.15) !important;
    font-weight: 700 !important;
}

.T-I.T-I-KE:hover {
    transform: translateY(-1px);
    filter: brightness(1.03);
}

/* ---------- EMAIL LIST ---------- */
.zA {
    background: var(--cream) !important;
    border-bottom: 1px solid #f6ced8 !important;
    color: var(--brown) !important;
}

.zA:nth-child(even) {
    background: #fff6f8 !important;
}

.zA:hover {
    background: #ffe3eb !important;
}

/* unread */
.zA.zE {
    background: #ffdce6 !important;
    font-weight: 700 !important;
}

/* ---------- EMAIL PANELS ---------- */
.a3s,
.ii.gt,
.adn.ads,
.hx {
    background: var(--cream) !important;
    color: var(--brown) !important;
}

/* ---------- BUTTONS ---------- */
button,
[role="button"] {
    border-radius: 14px !important;
}

/* ---------- POPUPS / MENUS ---------- */
.J-M,
.b8,
.Kj-JD,
.aO7 {
    background: #fff9f7 !important;
    color: var(--brown) !important;
    border: 1px solid #f1bac8 !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 24px rgba(120, 77, 86, 0.14) !important;
}

/* ---------- TEXT ---------- */
.yW span,
.bog,
.yP,
.zF,
.xY,
.a3s {
    color: var(--brown) !important;
}

/* ---------- LINKS ---------- */
a {
    color: #c75f7d !important;
}

/* ---------- INPUTS ---------- */
input,
textarea,
select {
    background: #fffaf7 !important;
    color: var(--brown) !important;
    border-radius: 12px !important;
}

/* ---------- CHECKBOX / TOOL AREAS ---------- */
.G-atb,
.aqJ,
.aqK {
    background: #fff5f6 !important;
}

/* ---------- SCROLLBAR ---------- */
::-webkit-scrollbar {
    width: 12px;
    height: 12px;
}

::-webkit-scrollbar-track {
    background: #fff2f5;
}

::-webkit-scrollbar-thumb {
    background: #e6a1b3;
    border-radius: 999px;
    border: 3px solid #fff2f5;
}

::-webkit-scrollbar-thumb:hover {
    background: #d7839c;
}

/* ---------- ROUND MORE THINGS ---------- */
div,
table,
tr,
td {
    scrollbar-color: #e6a1b3 #fff2f5;
}

/* ---------- SOFT CARD LOOK ---------- */
.zA,
.adn.ads,
.Kj-JD {
    transition:
        background-color 0.15s ease,
        box-shadow 0.15s ease,
        transform 0.15s ease;
}

/* ---------- CUTE GINGHAM FEEL ---------- */
.aeN {
    background-image:
        linear-gradient(
            90deg,
            rgba(255,255,255,.17) 50%,
            transparent 50%
        ),
        linear-gradient(
            rgba(255,255,255,.17) 50%,
            transparent 50%
        ) !important;

    background-size: 28px 28px !important;
}
}
